<script lang="ts">
 import {onMount} from 'svelte';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {totals,type MetricsGateway,type MetricReport} from '../application/metrics';
 let {gateway,admin=false}:{gateway:MetricsGateway;admin?:boolean}=$props();
 const {locale}=useLocale();let period=$state<7|30|90>(30),report=$state<MetricReport|null>(null),busy=$state(true),failed=$state(false),generation=0;
 const sum=$derived(report?totals(report):null);
 const max=$derived(Math.max(1,...(report?.days.map(day=>day.completions)||[])));
 async function load(value:7|30|90=period){const request=++generation;period=value;busy=true;failed=false;report=null;try{const next=await gateway.report(admin,value);if(request===generation)report=next;}catch{if(request===generation)failed=true;}finally{if(request===generation)busy=false;}}
 onMount(()=>{void load();return()=>{generation++;};});
</script>
<section class="metrics"><h1>{admin?text($locale,'Сайтқа шолу','Обзор сайта'):text($locale,'Командалар статистикасы','Статистика команд')}</h1>
 <div class="periods" role="group" aria-label={text($locale,'Кезең','Период')}>{#each [7,30,90] as value}<button class="button subtle" aria-pressed={period===value} onclick={()=>load(value as 7|30|90)}>{value} {text($locale,'күн','дней')}</button>{/each}</div>
 {#if busy}<p role="status">{text($locale,'Статистика жүктелуде…','Загрузка статистики…')}</p>{:else if failed}<p role="alert">{text($locale,'Статистика қолжетімсіз немесе рұқсат жоқ.','Статистика недоступна или нет доступа.')}</p><button class="button" onclick={()=>load()}>{text($locale,'Қайталау','Повторить')}</button>{:else if report&&sum}
 <p class="muted">{text($locale,'Жинау басталды:','Начало сбора:')} {new Date(report.startedAt).toLocaleDateString($locale==='ru'?'ru-RU':'kk-KZ',{timeZone:'UTC'})}. UTC.</p>
 <dl>{#if admin}<div><dt>{text($locale,'Жаңа расталған аккаунттар','Новые подтверждённые аккаунты')}</dt><dd>{sum.verified}</dd></div>{/if}<div><dt>{text($locale,'Белсенді оқырмандар','Активные читатели')}</dt><dd>{report.periodReaders}</dd></div><div><dt>{text($locale,'Жарияланған аудармалар','Опубликованные переводы')}</dt><dd>{sum.publications}</dd></div><div><dt>{text($locale,'Аяқталған оқулар','Завершённые чтения')}</dt><dd>{sum.completions}</dd></div><div><dt>{text($locale,'Кітапханаға қосу','Добавления в библиотеку')}</dt><dd>{sum.libraries}</dd></div><div><dt>{text($locale,'Жаңа хабарлама жазылымдары','Новые подписки на уведомления')}</dt><dd>{sum.subscriptions}</dd></div>{#if admin}<div><dt>{text($locale,'Жаңа бағалар','Новые оценки')}</dt><dd>{sum.ratings}</dd></div>{/if}</dl>
 {#if !Object.values(sum).some(Boolean)&&report.periodReaders===0}<p>{text($locale,'Бұл кезеңде тіркелген оқиғалар жоқ.','В этом периоде нет зарегистрированных событий.')}</p>{/if}
 <h2>{text($locale,'Күндер бойынша аяқталған оқулар','Завершённые чтения по дням')}</h2>
 <div class="bars" aria-hidden="true">{#each report.days as day}<span style:height={`${day.completions===0?0:Math.max(2,day.completions/max*100)}%`}></span>{/each}</div>
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (keyboard users must scroll the data table at narrow widths) -->
 <section class="table-scroll" tabindex="0" aria-label={text($locale,'Күнделікті статистика кестесі','Таблица статистики по дням')}><table><caption>{text($locale,'График деректері және күнделікті оқиғалар','Данные графика и события по дням')}</caption><thead><tr><th scope="col">{text($locale,'Күн','Дата')}</th>{#if admin}<th scope="col">{text($locale,'Расталған','Подтверждённые')}</th>{/if}<th scope="col">{text($locale,'Оқырмандар','Читатели')}</th><th scope="col">{text($locale,'Аяқталған','Завершённые')}</th><th scope="col">{text($locale,'Жарияланымдар','Публикации')}</th><th scope="col">{text($locale,'Кітапхана','Библиотека')}</th><th scope="col">{text($locale,'Жазылымдар','Подписки')}</th>{#if admin}<th scope="col">{text($locale,'Бағалар','Оценки')}</th>{/if}</tr></thead><tbody>{#each report.days as day}<tr><th scope="row">{day.date}</th>{#if admin}<td>{day.verified}</td>{/if}<td>{day.readers}</td><td>{day.completions}</td><td>{day.publications}</td><td>{day.libraries}</td><td>{day.subscriptions}</td>{#if admin}<td>{day.ratings}</td>{/if}</tr>{/each}</tbody></table></section>
 <p class="muted">{text($locale,'Белсенді оқырман — сервер қабылдаған прогресі бар аккаунт. Аяқталған оқу — соңғы бетке жеткен прогресс; бір аккаунт пен аудармаға күніне бір рет. Бұл адам оқығанының кепілі емес және сурет сұраулары есептелмейді.','Активный читатель — аккаунт с принятым сервером прогрессом. Завершённое чтение — прогресс на последней странице; один раз на аккаунт и перевод в день. Это не гарантия чтения человеком; запросы изображений не учитываются.')}</p>
 <p class="muted">{admin?text($locale,'Бағалар — алғашқы бағалау; кітапхана мен жазылымдар — жаңа қосылу оқиғалары, ағымдағы қалдық емес.','Оценки — первое оценивание; библиотека и подписки — новые добавления, а не текущий остаток.'):text($locale,'Тек өзіңіз мүше болған мақұлданған командалар. Кітапхана мен жазылымдар — осы команданы таңдаған оқырмандардың жаңа қосылулары. Жалпы командаға жазылу функциясы жоқ.','Только одобренные команды, в которых вы состоите. Библиотека и подписки — новые добавления читателей, выбравших эту команду. Отдельной подписки на команду нет.')}</p>
 {/if}</section>
<style>.metrics{padding:24px 16px;max-width:1100px;margin:auto}.metrics h1{font-size:24px;margin:0 0 20px}.metrics h2{font-size:18px;margin-top:28px}.periods{display:flex;gap:8px;flex-wrap:wrap}.periods [aria-pressed=true]{border-color:var(--accent);color:var(--accent)}dl{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:0 24px;margin:24px 0}dl>div{padding:16px 0;border-bottom:1px solid var(--line)}dt{font-size:14px;color:var(--muted)}dd{font-size:26px;margin:8px 0 0;font-variant-numeric:tabular-nums}.muted{font-size:14px;line-height:1.6;color:var(--muted)}.bars{display:flex;align-items:end;gap:2px;height:150px;border-bottom:1px solid var(--line);padding-top:8px}.bars span{flex:1;min-width:1px;background:var(--accent)}.table-scroll{overflow:auto;margin:20px 0;max-height:520px}table{width:100%;border-collapse:collapse;font-size:13px;font-variant-numeric:tabular-nums}caption{text-align:left;padding:8px 0;color:var(--muted)}th,td{text-align:right;border-bottom:1px solid var(--line);padding:10px;white-space:nowrap}th:first-child{text-align:left}thead th{position:sticky;top:0;background:var(--panel)}button{min-height:44px}@media(min-width:720px){.metrics{padding:32px}}</style>
